// SEGURO: usar textContent para texto simples do utilizador
function mostrarComentarioSeguro(comentario) {
  const p = document.createElement('p');
  p.textContent = comentario; // qualquer HTML é tratado como texto literal
  document.querySelector('#comentarios').appendChild(p);
}

