  if (texto.includes('leite')) {
    item.classList.add('comprado');
  }
});

const botaoTema = document.querySelector('#toggle-tema');

botaoTema.addEventListener('click', () => {
  const escuroAtivo = document.body.classList.toggle('tema-escuro');
  botaoTema.setAttribute('aria-pressed', String(escuroAtivo));
  botaoTema.textContent = escuroAtivo ? 'Modo claro' : 'Modo escuro';
});

function adicionarTarefa(texto) {
  const lista = document.querySelector('#lista-tarefas');

  const item = document.createElement('li');
  item.textContent = texto;

  const botaoRemover = document.createElement('button');
  botaoRemover.textContent = 'Remover';
  botaoRemover.addEventListener('click', () => item.remove());

  item.appendChild(botaoRemover);
  lista.appendChild(item);
}

function renderizarComentarios(comentarios) {
  const contentor = document.querySelector('#caixa-comentarios');
  contentor.replaceChildren(); // limpa o conteúdo anterior sem usar innerHTML = ''

  comentarios.forEach((texto, indice) => {
    const div = document.createElement('div');
    div.classList.add('comentario');

    if (indice % 2 === 0) {
      div.classList.add('par');
    }

    div.dataset.indice = String(indice);
    div.textContent = texto; // texto do utilizador nunca passa por innerHTML

    contentor.appendChild(div);
  });
}
